UPDATE vendors SET pickup='{"ru":"Мясникяна, 16 — кондитерская Вови, у рынка","hy":"Մյասնիկյան 16 — Վովիի հրուշակեղենի խանութ, շուկայի մոտ","ka":"მიასნიკიანის 16 — ვოვის საკონდიტრო, ბაზართან"}' WHERE id='akhalkalaki-vypechka' AND (pickup IS NULL OR pickup<>'{"ru":"Мясникяна, 16 — кондитерская Вови, у рынка","hy":"Մյասնիկյան 16 — Վովիի հրուշակեղենի խանութ, շուկայի մոտ","ka":"მიასნიკიანის 16 — ვოვის საკონდიტრო, ბაზართან"}');
